// Verify the padded-LEB memarg fixtures generated by memarg-padding-fixtures.py.
// analyzeHeadless <proj> <name> -import memarg_padding.wasm -import memarg_padding64.wasm
//     -import memarg_padding_lenient.wasm -noanalysis
//     -scriptPath test-scripts -postScript CheckMemargPadding.java
//
// Pins, per function: the exact instruction sequence (mnemonic, byte length, operand
// text - i.e. instruction boundaries and the align/memidx/offset decode), the memory
// selection of every load/store (ACCESS space + address width + the memidx stride
// multiply in the pcode) and the emulated i32 result (the effective address: which
// memory's bytes actually come back). The fully padded 26-byte v128.load also
// exercises the emulator's memarg read buffer (MAX_MEMARG_INSTRUCTION_BYTES).
//@category Test.Wasm
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.plugin.core.analysis.AutoAnalysisManager;
import ghidra.app.script.GhidraScript;
import ghidra.program.emulation.WasmEmulationHelper;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.Instruction;
import ghidra.program.model.listing.Program;
import ghidra.program.model.pcode.PcodeOp;
import ghidra.program.model.pcode.Varnode;

public class CheckMemargPadding extends GhidraScript {

	private static final long MEMORY_STRIDE = 0x08000000L;

	private void require(boolean condition, String detail) {
		if (!condition) throw new AssertionError(detail);
	}

	private void prepare() throws Exception {
		currentProgram.getOptions(Program.ANALYSIS_PROPERTIES)
			.setInt("Wasm Pre-Analyzer.C Stack Pointer", -1);
		AutoAnalysisManager manager = AutoAnalysisManager.getAnalysisManager(currentProgram);
		manager.initializeOptions(currentProgram.getOptions(Program.ANALYSIS_PROPERTIES));
		manager.reAnalyzeAll(null);
		manager.waitForAnalysis(null, monitor);
	}

	/** One expected function: exact instruction sequence, memory selection, i32 result. */
	private static final class Case {
		final String name;
		/** "mnemonic|length|operand substring|..." - fields split on '|'. */
		final String[] insns;
		final String space;     // "memory" or "memory64"
		final int addrSize;     // 4 (i32 index) or 8 (i64 index)
		final boolean flagged;  // memidx present -> stride multiply in the pcode
		final long offset;      // static memarg offset
		final long result;      // expected emulated i32 return (unsigned)

		Case(String name, String[] insns, String space, int addrSize,
				boolean flagged, long offset, long result) {
			this.name = name;
			this.insns = insns;
			this.space = space;
			this.addrSize = addrSize;
			this.flagged = flagged;
			this.offset = offset;
			this.result = result;
		}
	}

	// memarg_padding.wasm: two 32-bit memories; every access lands in `memory` (size 4).
	private static final Case[] MODULE_A = {
		new Case("scalar_pad2",
			new String[] {".locals|1", "i32.const|2",
				"i32.load|7|align=0x2 memidx=0x1 offset=0x0", "end|1"},
			"memory", 4, true, 0, 0x88776655L),
		new Case("scalar_pad5",
			new String[] {".locals|1", "i32.const|2",
				"i32.load|21|align=0x2 memidx=0x1 offset=0x0", "end|1"},
			"memory", 4, true, 0, 0x88776655L),
		new Case("scalar_plain_flag",
			new String[] {".locals|1", "i32.const|2",
				"i32.load|4|align=0x2 memidx=0x1 offset=0x0", "end|1"},
			"memory", 4, true, 0, 0x88776655L),
		new Case("scalar_plain_unflag",
			new String[] {".locals|1", "i32.const|2",
				"i32.load|3|align=0x2 offset=0x0", "end|1"},
			"memory", 4, false, 0, 0x44332211L),
		new Case("scalar_unflag_pad",
			new String[] {".locals|1", "i32.const|2",
				"i32.load|16|align=0x2 offset=0x0", "end|1"},
			"memory", 4, false, 0, 0x44332211L),
		new Case("atomic_pad",
			new String[] {".locals|1", "i32.const|2",
				"i32.atomic.load|22|align=0x2 memidx=0x1 offset=0x0", "end|1"},
			"memory", 4, true, 0, 0x88776655L),
		new Case("store_pad",
			new String[] {".locals|1", "i32.const|2", "i32.const|6",
				"i32.store|16|align=0x2 memidx=0x1 offset=0x4",
				"i32.const|2", "i32.load|16|align=0x2 memidx=0x1 offset=0x4", "end|1"},
			"memory", 4, true, 4, 0x12345678L),
	};

	// memarg_padding64.wasm: memory 1 is 64-bit indexed; its accesses land in
	// `memory64` (size 8) through the "(i64 index)" decoders.
	private static final Case[] MODULE_B = {
		new Case("simd_pad_v128",
			new String[] {".locals|1", "i64.const|2",
				"v128.load|26|align=0x4|memidx=0x1|offset=0x0|(i64 index)",
				"i32x4.extract_lane|3", "end|1"},
			"memory64", 8, true, 0, 0xccbbaa99L),
		new Case("scalar_pad_mem64",
			new String[] {".locals|1", "i64.const|2",
				"i32.load|21|align=0x2|memidx=0x1|offset=0x0|(i64 index)", "end|1"},
			"memory64", 8, true, 0, 0xccbbaa99L),
		new Case("simd_plain",
			new String[] {".locals|1", "i64.const|2",
				"v128.load|5|align=0x0|memidx=0x1|offset=0x0|(i64 index)",
				"i32x4.extract_lane|3", "end|1"},
			"memory64", 8, true, 0, 0xccbbaa99L),
	};

	// memarg_padding_lenient.wasm: deliberately wabt-invalid (alignment hint 130);
	// pins that a spec-invalid module still imports and still decodes UNFLAGGED, with
	// the full multi-byte value (bit 6 of 130 is clear).
	private static final Case[] MODULE_C = {
		new Case("scalar_unflag_pad130",
			new String[] {".locals|1", "i32.const|2",
				"i32.load|7|align=0x82 offset=0x0", "end|1"},
			"memory", 4, false, 0, 0x44332211L),
	};

	private static boolean hasConst(PcodeOp op, long value) {
		for (Varnode in : op.getInputs()) {
			if (in.isConstant() && in.getOffset() == value) {
				return true;
			}
		}
		return false;
	}

	private long emulate(Function f) throws Exception {
		EmulatorHelper emu = new EmulatorHelper(currentProgram);
		try {
			Address ret = currentProgram.getAddressFactory().getDefaultAddressSpace()
				.getAddress(0x80000000L);
			WasmEmulationHelper helper = new WasmEmulationHelper(emu.getLanguage());
			helper.simulateCall(emu.getEmulator(), ret.getOffset(),
				f.getEntryPoint().getOffset(), new BigInteger[0]);
			String error = null;
			boolean returned = false;
			for (int steps = 0; steps < 1000; steps++) {
				if (emu.getExecutionAddress().equals(ret)) { returned = true; break; }
				if (!emu.step(monitor)) { error = emu.getLastError(); break; }
			}
			require(returned && error == null, f.getName() + " did not return: " + error);
			byte[] value = emu.readMemory(currentProgram.getRegister("s0").getAddress(), 4);
			long actual = 0;
			for (int i = 3; i >= 0; i--) actual = (actual << 8) | (value[i] & 0xff);
			return actual;
		}
		finally { emu.dispose(); }
	}

	private void check(Case c) throws Exception {
		Function f = null;
		for (Function candidate : currentProgram.getFunctionManager().getFunctions(true)) {
			if (candidate.getName().equals(c.name)) { f = candidate; break; }
		}
		require(f != null, "missing function " + c.name);

		List<Instruction> list = new ArrayList<>();
		for (Instruction insn : currentProgram.getListing().getInstructions(f.getBody(), true)) {
			list.add(insn);
		}
		require(list.size() == c.insns.length,
			c.name + ": expected " + c.insns.length + " instructions, got " + list.size());
		long covered = 0;
		for (int i = 0; i < list.size(); i++) {
			Instruction insn = list.get(i);
			String[] spec = c.insns[i].split("\\|");
			require(insn.getMnemonicString().equals(spec[0]),
				c.name + " insn " + i + ": expected " + spec[0] + ", got " +
				insn.getMnemonicString());
			require(insn.getLength() == Integer.parseInt(spec[1]),
				c.name + " " + spec[0] + ": expected length " + spec[1] + ", got " +
				insn.getLength());
			String text = insn.toString();
			for (int k = 2; k < spec.length; k++) {
				require(text.contains(spec[k]),
					c.name + " " + spec[0] + ": missing operand '" + spec[k] + "' in '" +
					text + "'");
			}
			covered += insn.getLength();
		}
		require(covered == f.getBody().getNumAddresses(),
			c.name + ": instructions cover " + covered + " of " +
			f.getBody().getNumAddresses() + " body bytes");

		for (Instruction insn : list) {
			String mnemonic = insn.getMnemonicString();
			if (!mnemonic.contains("load") && !mnemonic.contains("store")) {
				continue;
			}
			String text = insn.toString();
			require(text.contains("memidx") == c.flagged,
				c.name + ": memidx operand presence wrong in '" + text + "'");
			boolean hasStride = false, hasOffset = false;
			for (PcodeOp op : insn.getPcode()) {
				if (op.getOpcode() == PcodeOp.LOAD || op.getOpcode() == PcodeOp.STORE) {
					String actual = currentProgram.getAddressFactory()
						.getAddressSpace((int) op.getInput(0).getOffset()).getName();
					require(actual.equals(c.space), c.name + " wrong space " + actual);
					require(op.getInput(1).getSize() == c.addrSize,
						c.name + " address width " + op.getInput(1).getSize());
				}
				if (op.getOpcode() == PcodeOp.INT_MULT) {
					hasStride = hasConst(op, MEMORY_STRIDE);
				}
				if (op.getOpcode() == PcodeOp.INT_ADD) {
					hasOffset |= hasConst(op, c.offset);
				}
			}
			require(hasStride == c.flagged,
				c.name + ": flagged=" + c.flagged + " but stride multiply present=" +
				hasStride);
			require(hasOffset, c.name + ": no INT_ADD with the static offset " + c.offset);
		}

		long result = emulate(f);
		require(result == c.result, c.name + " expected=0x" + Long.toHexString(c.result) +
			" got=0x" + Long.toHexString(result));
		println("MEMARG-PADDING-OK " + c.name + " result=0x" + Long.toHexString(result));
	}

	@Override
	public void run() throws Exception {
		prepare();
		String name = currentProgram.getName();
		Case[] cases;
		String block1Space;
		if (name.equals("memarg_padding64.wasm")) {
			cases = MODULE_B;
			block1Space = "memory64";
		}
		else if (name.equals("memarg_padding_lenient.wasm")) {
			cases = MODULE_C;
			block1Space = null; // single-memory module: only .memory0 exists
		}
		else {
			cases = MODULE_A;
			block1Space = "memory";
		}
		int count = 0;
		for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
			Case c = null;
			for (Case candidate : cases) {
				if (candidate.name.equals(f.getName())) { c = candidate; break; }
			}
			require(c != null, "unexpected function " + f.getName());
			check(c);
			count++;
		}
		require(count == cases.length, "functions=" + count + " expected " + cases.length);
		if (block1Space != null) {
			String block1 = currentProgram.getMemory().getBlock(".memory1").getStart()
				.getAddressSpace().getName();
			require(block1.equals(block1Space), ".memory1 space " + block1);
		}
		else {
			String block0 = currentProgram.getMemory().getBlock(".memory0").getStart()
				.getAddressSpace().getName();
			require(block0.equals("memory"), ".memory0 space " + block0);
		}
		println("MEMARG-PADDING " + name + " functions=" + count + " passed");
	}
}
